from collections import Counter, defaultdict, deque

def transform(grid):
    H, W = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = max(cnt, key=lambda k: cnt[k])
    seen = [[False]*W for _ in range(H)]
    bycolor = defaultdict(list)
    for i in range(H):
        for j in range(W):
            if grid[i][j] != bg and not seen[i][j]:
                c = grid[i][j]
                q = deque([(i, j)]); seen[i][j] = True; cells = []
                while q:
                    r, cc = q.popleft(); cells.append((r, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] == c:
                            seen[nr][nc] = True; q.append((nr, nc))
                bycolor[c].append(cells)
    targets = {}
    for c, ls in bycolor.items():
        if len(ls) == 1 and len(ls[0]) > 1:
            targets[c] = ls[0]
    out = [row[:] for row in grid]
    if not targets:
        return out

    def to_grid(cells):
        rs = [r for r, _ in cells]; cs = [c for _, c in cells]
        r0, c0 = min(rs), min(cs)
        h = max(rs) - r0 + 1; w = max(cs) - c0 + 1
        g = [[0]*w for _ in range(h)]
        for r, c in cells:
            g[r - r0][c - c0] = 1
        return g

    def collapse(g):
        g = [row[:] for row in g]
        changed = True
        while changed and len(g) > 1:
            changed = False
            keep = [0]
            for i in range(1, len(g)):
                if g[i] != g[keep[-1]]:
                    keep.append(i)
            if len(keep) < len(g):
                g = [g[i] for i in keep]; changed = True
        changed = True
        while changed and len(g[0]) > 1:
            changed = False
            cols = [[g[i][j] for i in range(len(g))] for j in range(len(g[0]))]
            keep = [0]
            for j in range(1, len(cols)):
                if cols[j] != cols[keep[-1]]:
                    keep.append(j)
            if len(keep) < len(cols):
                g = [[g[i][j] for j in keep] for i in range(len(g))]; changed = True
        return g

    def canon(cells):
        return collapse(to_grid(cells))

    def dihedral(g):
        outs = []
        cur = g
        for _ in range(4):
            outs.append(cur)
            outs.append([row[::-1] for row in cur])
            h, w = len(cur), len(cur[0])
            cur = [[cur[h - 1 - r][c] for r in range(h)] for c in range(w)]
        return outs

    tcans = {t: canon(tc) for t, tc in targets.items()}
    for c, ls in bycolor.items():
        if c in targets:
            continue
        for cells in ls:
            g = canon(cells)
            best = None
            for t, tg in tcans.items():
                for img in dihedral(g):
                    if img == tg:
                        key = (True, len(targets[t]))
                        if best is None or key > best[0]:
                            best = (key, t)
                        break
            if best is not None:
                for r, cc in cells:
                    out[r][cc] = best[1]
    return out
